package com.iotdevice.firmware

import java.security.{SecureRandom, MessageDigest}
import javax.crypto.{Cipher, KeyGenerator, SecretKey}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec, IvParameterSpec}
import java.util.Base64
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

object CryptoConfig {
  val GCM_TAG_LENGTH = 128
  val GCM_IV_LENGTH = 12
  val AES_KEY_LENGTH = 256
  val KEY_ROTATION_INTERVAL_MS = 3600000L // 1 hour
  val AUDIT_RETENTION_DAYS = 90
}

case class DeviceIdentity(deviceId: String, firmwareVersion: String, enrollmentTime: Instant)

case class AuditEntry(
  timestamp: Instant,
  deviceId: String,
  action: String,
  encryptedPayload: String,
  iv: String,
  keyEpoch: Long
)

class KeyDerivationService(masterSecret: Array[Byte]) {
  private val random = new SecureRandom()
  private var currentEpoch: Long = 0L
  private var lastRotation: Long = System.currentTimeMillis()
  private val keyCache = new ConcurrentHashMap[Long, SecretKey]()

  def deriveKey(epoch: Long, context: String): SecretKey = {
    val cacheKey = epoch * 31 + context.hashCode
    val cached = keyCache.get(cacheKey)
    if (cached != null) return cached

    val digest = MessageDigest.getInstance("SHA-256")
    digest.update(masterSecret)
    digest.update(epoch.toString.getBytes("UTF-8"))
    digest.update(context.getBytes("UTF-8"))
    val keyBytes = digest.digest()
    val key = new SecretKeySpec(keyBytes, "AES")
    keyCache.put(cacheKey, key)
    key
  }

  def getCurrentEpoch: Long = {
    val now = System.currentTimeMillis()
    if (now - lastRotation >= CryptoConfig.KEY_ROTATION_INTERVAL_MS) {
      currentEpoch += 1
      lastRotation = now
    }
    currentEpoch
  }

  def generateIv(): Array[Byte] = {
    val iv = new Array[Byte](CryptoConfig.GCM_IV_LENGTH)
    random.nextBytes(iv)
    iv
  }
}

class SecureAuditLogger(keyService: KeyDerivationService, device: DeviceIdentity) {
  private val auditLog = mutable.ArrayBuffer[AuditEntry]()
  private val encryptionContext = s"audit-${device.deviceId}"

  def logEvent(action: String, payload: String): AuditEntry = {
    val epoch = keyService.getCurrentEpoch
    val key = keyService.deriveKey(epoch, encryptionContext)
    val iv = keyService.generateIv()
    val encrypted = encrypt(payload, key, iv)
    val entry = AuditEntry(
      timestamp = Instant.now(),
      deviceId = device.deviceId,
      action = action,
      encryptedPayload = Base64.getEncoder.encodeToString(encrypted),
      iv = Base64.getEncoder.encodeToString(iv),
      keyEpoch = epoch
    )
    auditLog.synchronized { auditLog += entry }
    entry
  }

  def retrieveEvent(index: Int): Option[String] = {
    auditLog.synchronized {
      if (index >= 0 && index < auditLog.length) {
        val entry = auditLog(index)
        val key = keyService.deriveKey(entry.keyEpoch, encryptionContext)
        val iv = Base64.getDecoder.decode(entry.iv)
        val ciphertext = Base64.getDecoder.decode(entry.encryptedPayload)
        Some(decrypt(ciphertext, key, iv))
      } else None
    }
  }

  private def encrypt(plaintext: String, key: SecretKey, iv: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(CryptoConfig.GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)
    cipher.updateAAD(device.deviceId.getBytes("UTF-8"))
    cipher.doFinal(plaintext.getBytes("UTF-8"))
  }

  private def decrypt(ciphertext: Array[Byte], key: SecretKey, iv: Array[Byte]): String = {
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(CryptoConfig.GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.updateAAD(device.deviceId.getBytes("UTF-8"))
    new String(cipher.doFinal(ciphertext), "UTF-8")
  }
}

class FirmwareCommandHandler(logger: SecureAuditLogger, keyService: KeyDerivationService, device: DeviceIdentity) {
  private val commandContext = s"cmd-${device.deviceId}"
  private var lastCommandNonce: Option[Array[Byte]] = None

  def processCommand(encryptedCommand: Array[Byte], commandIv: Array[Byte], epoch: Long): String = {
    val key = keyService.deriveKey(epoch, commandContext)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(CryptoConfig.GCM_TAG_LENGTH, commandIv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.updateAAD(s"${device.deviceId}:${device.firmwareVersion}".getBytes("UTF-8"))
    val command = new String(cipher.doFinal(encryptedCommand), "UTF-8")
    logger.logEvent("COMMAND_RECEIVED", command)
    executeCommand(command)
  }

  def sendResponse(response: String, epoch: Long): (Array[Byte], Array[Byte]) = {
    val key = keyService.deriveKey(epoch, commandContext)
    val iv = keyService.generateIv()
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    val spec = new GCMParameterSpec(CryptoConfig.GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)
    cipher.updateAAD(s"${device.deviceId}:${device.firmwareVersion}".getBytes("UTF-8"))
    logger.logEvent("RESPONSE_SENT", response)
    (cipher.doFinal(response.getBytes("UTF-8")), iv)
  }

  private def executeCommand(command: String): String = {
    command match {
      case "STATUS" => s"OK:${device.firmwareVersion}:${Instant.now()}"
      case "REBOOT" => logger.logEvent("REBOOT_INITIATED", ""); "REBOOTING"
      case cmd if cmd.startsWith("CONFIG:") =>
        val config = cmd.stripPrefix("CONFIG:")
        logger.logEvent("CONFIG_UPDATE", config)
        s"CONFIG_APPLIED:$config"
      case _ => "UNKNOWN_COMMAND"
    }
  }
}

object DeviceFirmware extends App {
  val masterSecret = new Array[Byte](32)
  new SecureRandom().nextBytes(masterSecret)

  val device = DeviceIdentity("IOT-SENSOR-001", "2.4.1", Instant.now())
  val keyService = new KeyDerivationService(masterSecret)
  val logger = new SecureAuditLogger(keyService, device)
  val handler = new FirmwareCommandHandler(logger, keyService, device)

  logger.logEvent("DEVICE_BOOT", s"Firmware ${device.firmwareVersion} started")
  println(s"Device ${device.deviceId} initialized with firmware ${device.firmwareVersion}")
}
